// Read-only probe: what do stored ElevenLabs conversations look like?
const BASE = "https://api.elevenlabs.io/v1/convai/conversations";
const headers = { "xi-api-key": process.env.ELEVENLABS_API_KEY ?? "" };

async function get(url: string): Promise<Record<string, unknown>> {
  const res = await fetch(url, { headers });
  if (!res.ok) throw new Error(`${res.status} ${(await res.text()).slice(0, 300)}`);
  return (await res.json()) as Record<string, unknown>;
}

const pick = (o: Record<string, unknown>, keys: string[]) =>
  Object.fromEntries(keys.map((k) => [k, o[k]]));

const listing = await get(`${BASE}?page_size=3`);
const convs = (listing.conversations ?? []) as Record<string, unknown>[];
console.log("listed:", convs.length, "has_more:", listing.has_more);
for (const c of convs) {
  console.log(
    pick(c, ["conversation_id", "agent_name", "status", "call_duration_secs", "message_count"]),
  );
}

if (convs.length > 0) {
  const detail = await get(`${BASE}/${convs[0].conversation_id}`);
  console.log("detail keys:", Object.keys(detail).sort());
  console.log("user_id:", detail.user_id);
  const transcript = (detail.transcript ?? []) as Record<string, unknown>[];
  console.log("turns:", transcript.length);
  if (transcript.length > 0) {
    console.log("turn keys:", Object.keys(transcript[0]).sort());
    console.log(
      "roles:",
      transcript.slice(0, 6).map((t) => t.role),
    );
  }
  console.log("metadata keys:", Object.keys((detail.metadata ?? {}) as object).sort());
  console.log("analysis keys:", Object.keys((detail.analysis ?? {}) as object).sort());
}

