// Read-only: which visitor ids own the most recent stored ElevenLabs calls?
const BASE = "https://api.elevenlabs.io/v1/convai/conversations";
const headers = { "xi-api-key": process.env.ELEVENLABS_API_KEY ?? "" };

const listing = (await (await fetch(`${BASE}?page_size=8`, { headers })).json()) as {
  conversations?: { conversation_id: string; agent_name?: string }[];
};
const counts = new Map<string, number>();
for (const c of listing.conversations ?? []) {
  const detail = (await (await fetch(`${BASE}/${c.conversation_id}`, { headers })).json()) as {
    user_id?: string | null;
  };
  const tail = detail.user_id ? detail.user_id.slice(-6) : "none";
  counts.set(tail, (counts.get(tail) ?? 0) + 1);
}
console.log("owner id tails of the 8 newest calls:", Object.fromEntries(counts));

