"use client";

import { useMemo, useState } from "react";
import { TopBar } from "./top-bar";
import { Sidebar, MobileDrawer, type NavId } from "./nav";
import { I18nContext } from "./i18n-context";
import { CallView } from "./call-view";
import { PersonasView } from "./personas-view";
import { ProvidersView } from "./providers-view";
import { ConversationsView } from "./conversations-view";
import { SettingsView } from "./settings-view";
import { TweaksPanel } from "./tweaks-panel";
import { RoutingNotice } from "./routing-notice";
import {
  PERSONAS,
  PROVIDERS,
  TOOLS_DEFAULT,
  resolvePersona,
  type Persona,
  type Provider,
  type Tool,
} from "@/lib/data";
import type { Lang } from "@/lib/lang";
import { makeT } from "@/lib/i18n";
import { useJaFonts } from "@/hooks/use-ja-fonts";
import { useRestartAfterRoute, useSessionRouting } from "@/hooks/use-session-routing";
import { useTweaks } from "@/hooks/use-tweaks";
import { useLmModel } from "@/hooks/use-lm-model";
import { useMediaQuery } from "@/hooks/use-media-query";
import { useNavKeys } from "@/hooks/use-nav-keys";
import { SOURCE_ENGINE, useResume, useSpendResumeAfterCall } from "@/hooks/use-resume";
import type { ConversationDetail } from "@/lib/conversations/types";
import { isLive } from "@/lib/realtime/types";
import { providerModelLabel, resolveLmModel } from "@/lib/realtime/lm-config";
import { providerExecLabel } from "@/lib/realtime/voice-config";
import { useRealtimeSession } from "@/lib/realtime/use-realtime-session";

export function AppShell() {
  const [tweaks, setTweak] = useTweaks();
  const [lmModelId, setLmModelId] = useLmModel();
  const [nav, setNav] = useState<NavId>("call");
  const [menuOpen, setMenuOpen] = useState(false);
  const [persona, setPersona] = useState<Persona>(PERSONAS[0]);
  // Transport + session language, and what happens when either changes
  // (JA failover, EN downgrade, new session on a live change).
  const routing = useSessionRouting();
  const { lang, provider } = routing;
  const [tools, setTools] = useState<Tool[]>(TOOLS_DEFAULT);
  const isMobile = useMediaQuery("(max-width: 760px)");
  // Bind the C/H/P/V/S section keys the sidebar advertises.
  useNavKeys(setNav);
  // A stored conversation the next call continues (its own transport, same persona).
  const resume = useResume(provider, persona);
  const memoryEnabled = tools.find((tool) => tool.name === "memory.recall")?.on ?? true;

  const session = useRealtimeSession({
    provider,
    persona,
    lang,
    lmModelId,
    voiceBargeIn: tweaks.voiceBargeIn,
    pushToTalk: tweaks.pushToTalk,
    resume: resume.armed,
    memoryEnabled,
  });
  useSpendResumeAfterCall(resume, session.callState, routing.restartPending);
  // What the UI shows as the active model — tracks the LM picker for cascade.
  const providerModel = providerModelLabel(provider, lmModelId, lang);
  // Execution mode — for cascade, computed from the resolved backends.
  const providerExec = providerExecLabel(provider, resolveLmModel(lmModelId).backend);
  useRestartAfterRoute(session, routing);
  const setLang = (next: Lang) => routing.changeLang(next, session);
  const setProvider = (next: Provider) => routing.changeProvider(next, session);
  // CONTINUE on a stored call: its persona, on the transport that stored it, in
  // the language it ran in.
  const continueConversation = (detail: ConversationDetail) => {
    const target = PERSONAS.find((p) => p.id === detail.personaId);
    const transport = PROVIDERS.find((p) => p.engine === SOURCE_ENGINE[detail.source]);
    if (!target || !transport || isLive(session.callState)) return;
    setPersona(target);
    routing.routeTo(transport, detail.lang, session);
    resume.select(detail);
    setNav("call");
  };
  // The persona as displayed in the session language (engines key off persona.id).
  const shown = resolvePersona(persona, lang);
  // The session language is also the UI locale.
  const t = useMemo(() => makeT(lang), [lang]);
  useJaFonts(tweaks.jaSans, tweaks.jaSerif);

  const sidebar = (onNav: (id: NavId) => void) => (
    <Sidebar
      nav={nav}
      setNav={onNav}
      persona={shown}
      provider={provider}
      providerModel={providerModel}
      providerExec={providerExec}
    />
  );

  return (
    <I18nContext.Provider value={t}>
      <div
        className={`tsubaki ${tweaks.dark ? "tsubaki-dark" : ""} ${isMobile ? "tb-mobile" : ""} ${tweaks.dock === "sidebar" && !isMobile ? "tb-tweaks-in-side" : ""} ${tweaks.dock === "top-right" && isMobile ? "tb-tweaks-in-bar" : ""}`}
        data-lang={lang}
      >
        <TopBar
          callState={session.callState}
          compact={isMobile}
          onMenu={isMobile ? () => setMenuOpen((o) => !o) : undefined}
          menuOpen={menuOpen}
        />
        <div className="tb-shell">
          {!isMobile && sidebar(setNav)}
          <main className="tb-main">
            <RoutingNotice notice={routing.notice} personaId={persona.id} />
            {nav === "call" && (
              <CallView
                tweaks={tweaks}
                session={session}
                persona={shown}
                provider={provider}
                providerModel={providerModel}
                lang={lang}
                setLang={setLang}
                compact={isMobile}
                tools={tools}
                resuming={resume.armed}
                onClearResume={resume.clear}
              />
            )}
            {nav === "conversations" && (
              <ConversationsView
                lang={lang}
                resumeId={resume.target?.id ?? null}
                callLive={isLive(session.callState)}
                onContinue={continueConversation}
                onClearResume={resume.clear}
              />
            )}
            {nav === "personas" && (
              <PersonasView
                persona={persona}
                setPersona={setPersona}
                provider={provider}
                lang={lang}
                setLang={setLang}
                accent={tweaks.accent}
              />
            )}
            {nav === "providers" && (
              <ProvidersView
                provider={provider}
                setProvider={setProvider}
                accent={tweaks.accent}
                lmModelId={lmModelId}
                setLmModelId={setLmModelId}
                lang={lang}
              />
            )}
            {nav === "settings" && (
              <SettingsView
                accent={tweaks.accent}
                lang={lang}
                setLang={setLang}
                tools={tools}
                setTools={setTools}
                muted={session.muted}
                onMutedChange={(m) => {
                  if (m !== session.muted) session.toggleMute();
                }}
                bargeIn={tweaks.voiceBargeIn}
                onBargeInChange={(v) => setTweak("voiceBargeIn", v)}
                pushToTalk={tweaks.pushToTalk}
                onPushToTalkChange={(v) => setTweak("pushToTalk", v)}
              />
            )}
          </main>
        </div>
        {/* Mobile reaches the same sections through a drawer hosting the
          desktop Sidebar. */}
        {isMobile && (
          <MobileDrawer open={menuOpen} onClose={() => setMenuOpen(false)}>
            {sidebar((id) => {
              setNav(id);
              setMenuOpen(false);
            })}
          </MobileDrawer>
        )}
        <TweaksPanel tweaks={tweaks} setTweak={setTweak} />
      </div>
    </I18nContext.Provider>
  );
}

import { useEffect, useState, type CSSProperties } from "react";
import { Hr, FieldRow, SwitchRow, ToolRow } from "./primitives";
import { useT } from "./i18n-context";
import { MicSelector } from "@/components/ui/mic-selector";
import { useAudioOutputDevices } from "@/hooks/use-audio-output-devices";
import { LangSwitch } from "./lang-switch";
import { VisitorIdField } from "./visitor-id-field";
import type { Tool } from "@/lib/data";
import type { Lang } from "@/lib/lang";

export function SettingsView({
  accent,
  lang,
  setLang,
  tools,
  setTools,
  muted,
  onMutedChange,
  bargeIn,
  onBargeInChange,
  pushToTalk,
  onPushToTalkChange,
}: {
  accent: string;
  /** Session language — interface and voice. */
  lang: Lang;
  setLang: (lang: Lang) => void;
  tools: Tool[];
  setTools: (updater: (prev: Tool[]) => Tool[]) => void;
  muted: boolean;
  onMutedChange: (m: boolean) => void;
  /** Voice barge-in — user speech interrupts the agent (OpenAI engine). */
  bargeIn: boolean;
  onBargeInChange: (v: boolean) => void;
  /** Push-to-talk — only the Send button ends a turn (cascade engine). */
  pushToTalk: boolean;
  onPushToTalkChange: (v: boolean) => void;
}) {
  const t = useT();
  const [device, setDevice] = useState("");
  const outputs = useAudioOutputDevices();
  const [out, setOut] = useState("");
  const [latency, setLatency] = useState(220);
  const [vad, setVad] = useState(0.65);
  const [denoise, setDenoise] = useState(true);

  // Default the output selection to the first real device once enumerated.
  useEffect(() => {
    if (!out && outputs.length > 0) setOut(outputs[0].deviceId);
  }, [out, outputs]);

  const accentColor = { accentColor: accent } as CSSProperties;
  const toggleTool = (name: string) =>
    setTools((prev) => prev.map((x) => (x.name === name ? { ...x, on: !x.on } : x)));

  return (
    <div className="tb-settings">
      <div className="tb-page-hd">
        <div>
          <div className="tb-h-eyebrow">{t("settings.eyebrow")}</div>
          <h1 className="tb-h1">{t("settings.title")}</h1>
          <p className="tb-lede">{t("settings.lede")}</p>
        </div>
      </div>

      <div className="tb-settings-grid">
        {/* GENERAL spans the full width so the 2×2 grid below keeps its order:
            AUDIO IN | AUDIO OUT, BEHAVIOUR | TOOLS. */}
        <section className="tb-settings-sec tb-settings-sec-wide">
          <Hr label={t("sec.general")} />
          <FieldRow label={t("field.language")} hint={t("field.language.hint")}>
            <LangSwitch lang={lang} onChange={setLang} />
          </FieldRow>
          <VisitorIdField />
        </section>

        <section className="tb-settings-sec">
          <Hr label={t("sec.audioIn")} />
          <FieldRow label={t("field.inputDevice")}>
            <MicSelector
              value={device}
              onValueChange={setDevice}
              muted={muted}
              onMutedChange={onMutedChange}
              className="w-full sm:w-full"
            />
          </FieldRow>
          <FieldRow label={t("field.level")}>
            <div className="tb-meter">
              <span style={{ width: "58%", background: accent }} />
            </div>
          </FieldRow>
          <FieldRow label={t("field.denoise")}>
            <SwitchRow value={denoise} onChange={setDenoise} />
          </FieldRow>
          <FieldRow label={t("field.vad")} hint={t("field.vad.hint", { v: vad.toFixed(2) })}>
            <input
              type="range"
              min="0"
              max="1"
              step="0.01"
              value={vad}
              onChange={(e) => setVad(parseFloat(e.target.value))}
              className="tb-range"
              style={accentColor}
            />
          </FieldRow>
        </section>

        <section className="tb-settings-sec">
          <Hr label={t("sec.audioOut")} />
          <FieldRow label={t("field.outputDevice")}>
            <select className="tb-select" value={out} onChange={(e) => setOut(e.target.value)}>
              {outputs.length === 0 ? (
                <option value="">System default</option>
              ) : (
                outputs.map((d) => (
                  <option key={d.deviceId} value={d.deviceId}>
                    {d.label}
                  </option>
                ))
              )}
            </select>
          </FieldRow>
          <FieldRow label={t("field.volume")}>
            <input type="range" defaultValue="70" className="tb-range" style={accentColor} />
          </FieldRow>
          <FieldRow label={t("field.spatial")}>
            <SwitchRow value={false} onChange={() => {}} />
          </FieldRow>
        </section>

        <section className="tb-settings-sec">
          <Hr label={t("sec.behaviour")} />
          <FieldRow label={t("field.latency")} hint={t("field.latency.hint", { ms: latency })}>
            <input
              type="range"
              min="80"
              max="600"
              step="10"
              value={latency}
              onChange={(e) => setLatency(parseInt(e.target.value))}
              className="tb-range"
              style={accentColor}
            />
            <div className="tb-range-scale">
              <span>80</span>
              <span>240</span>
              <span>400</span>
              <span>600</span>
            </div>
          </FieldRow>
          <FieldRow label={t("field.interruptions")} hint={t("field.interruptions.hint")}>
            <SwitchRow value={bargeIn} onChange={onBargeInChange} />
          </FieldRow>
          <FieldRow label={t("field.ptt")} hint={t("field.ptt.hint")}>
            <SwitchRow value={pushToTalk} onChange={onPushToTalkChange} />
          </FieldRow>
        </section>

        <section className="tb-settings-sec">
          <Hr label={t("sec.tools")} />
          {tools.map((tool) => (
            <ToolRow
              key={tool.name}
              name={tool.name}
              label={tool.label}
              on={tool.on}
              preview={tool.preview}
              onToggle={() => toggleTool(tool.name)}
            />
          ))}
        </section>
      </div>
    </div>
  );
}

