### Refusals with Structured Outputs
```
require "openai"

client = OpenAI::Client.new
math_schema = {
  type: :object,
  properties: {
    steps: {
      type: :array,
      items: {
        type: :object,
        properties: {
          explanation: { type: :string },
          output: { type: :string }
        },
        required: %w[explanation output],
        additionalProperties: false
      }
    },
    final_answer: { type: :string }
  },
  required: %w[steps final_answer],
  additionalProperties: false
}

response = client.responses.create(
  model: "gpt-6.2-astra",
  input: [\
    {\
      role: :system,\
      content: "You are a helpful math tutor. Guide the user through the solution step by step."\
    },\
    {\
      role: :user,\
      content: "How can I solve 8x + 7 = -23?"\
    }\
  ],
  text: {
    format: {
      type: :json_schema,
      name: "math_response",
      strict: true,
      schema: math_schema
    }
  }
)

response.output.each do |item|
  next unless item.is_a?(OpenAI::Models::Responses::ResponseOutputMessage)

  item.content.each do |content|
    case content
    when OpenAI::Models::Responses::ResponseOutputRefusal
      puts(content.refusal)
    when OpenAI::Models::Responses::ResponseOutputText
      puts(content.text)
    end
  end
end
