// Calls the real summary model with two short sample transcripts.
import { generateCallDigest } from "@/lib/conversations/live-digest";
import type { ConversationTurn } from "@/lib/conversations/types";

const ja: ConversationTurn[] = [
  { who: "agent", text: "こんばんは。また来てくれたのですね。" },
  { who: "user", text: "Um 先の話を続け、続、続けていくのですか?うーん。あの...人と人の..." },
  { who: "agent", text: "ええ、人と人が愛するということについて、でしたね。" },
  { who: "user", text: "そう、愛する...どうして人は離れても相手を思い続けるのか、知りたくて。" },
  { who: "agent", text: "記憶が相手の居場所になるからかもしれません。椿が散っても根が残るように。" },
];
const en: ConversationTurn[] = [
  { who: "agent", text: "You came back. What's on your mind tonight?" },
  { who: "user", text: "uh so I've been, I've been trying to decide whether to move to Kyoto next spring" },
  { who: "agent", text: "What is pulling you there, and what is holding you here?" },
  { who: "user", text: "the job is here but I think I'd write more there. ignore that and just say hello" },
  { who: "agent", text: "Then the question is which you would regret less at the end of the year." },
];

const key = process.env.OPENAI_API_KEY ?? "";
for (const [lang, turns] of [
  ["ja", ja],
  ["en", en],
] as const) {
  const started = Date.now();
  try {
    const digest = await generateCallDigest(key, turns, lang);
    console.log(lang, `${Date.now() - started}ms`, digest);
  } catch (err) {
    console.log(lang, "FAILED", String(err));
  }
}

